def minio_objects():
    total = 0
    for sub in BUCKETS:
        out = sh(["bash", "-c", "ls -1R %s/%s 2>/dev/null | grep -c . || true" % (MINIO_DATA, sub)])
        try:
            total += int(out or "0")
        except Exception:
            pass
    return total

def minio_bucket_counts():
    """Objects PER BUCKET.

    blockchain-raw is written continuously by the worker, so summing the three
    buckets fabricated a +10 "leak" on a route that never touches object storage.
    Every bucket is now reported separately and the route delta uses only the
    buckets a request can actually write.
    """
    out = {}
    for sub in BUCKETS:
        raw = sh(["bash", "-c", "ls -1R %s/%s 2>/dev/null | grep -c . || true" % (MINIO_DATA, sub)])
        try:
            out[sub] = int(raw or "0")
        except Exception:
            out[sub] = 0
    return out


def minio_objects():
    return sum(v for k, v in minio_bucket_counts().items() if "raw" not in k)


def minio_names():
    """Object NAMES, not only counts, for the buckets a request can write."""
    names = []
    for sub in BUCKETS:
        if "raw" in sub:
            continue
        out = sh(["bash", "-c", "ls -1R %s/%s 2>/dev/null | sed 's|^|%s/|' || true" % (MINIO_DATA, sub, sub)])
        for line in (out or "").splitlines():
            if line.strip():
                names.append(line.strip())
    return sorted(names)

return {"t": t0,
        "ch_sel": ch_selects_since(t0),
        "ch_ins": ch_inserts_since(t0),
        "obj": minio_objects(),
        "prov": provider_calls(base)}
